    if(
      todatetime(ri!nomination.createdOn)<#"_a-0000ea45-eea9-8000-9c49-011c48011c48_11589045",
      true,
      false)
  ),
  local!industries: #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050345"(
    refTypeId: #"_a-0000e6d2-8270-8000-9c03-011c48011c48_4014255",
    fetchTotalCount: false(),
    isActive: true,
    pagingInfo: #"SYSTEM_SYSRULES_pagingInfo"(
      startIndex: 1,
      batchSize: -1,
      sort: #"SYSTEM_SYSRULES_sortInfo"(field: "refId", ascending: true)
    ),
    returnCDT: true
  ),
  local!primaryIndustries: #"_a-0000e6bc-0703-8000-9bf8-011c48011c48_3534466"(
    returnCDT: true,
    isActive: true,
