    property(ri!nomination,"nominationTypeId",tointeger(null)) = #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3868562"),
    {#"_a-0000ea45-eea9-8000-9c49-011c48011c48_11672339"[2],#"_a-0000ea45-eea9-8000-9c49-011c48011c48_11672339"[1]},{#"_a-0000ea45-eea9-8000-9c49-011c48011c48_11672339"[3],#"_a-0000ea45-eea9-8000-9c49-011c48011c48_11672339"[1]})
  ),
  local!nomPrimaryIndustry: index(
    local!primaryIndustries,
    wherecontains(
      property(
        ri!nomination,
        "primaryIndustryId",
