                  #"SYSTEM_SYSRULES_gridLayoutHeaderCell"(label: "Level of Proficiency")
                },
                columnConfigs: {
                  #"SYSTEM_SYSRULES_gridLayoutColumnConfig"(width: "DISTRIBUTE"),
                  #"SYSTEM_SYSRULES_gridLayoutColumnConfig"(width: "DISTRIBUTE"),

                },
                rows: #"SYSTEM_SYSRULES_forEach"(
                  items: ri!candidateLanguageSkills,
